// Reel locks (or bubble reveals) animate one settled day's pool debit.
// Duplicate events and center/bonus prizes never spend the pool twice.
export function revealedPoolWei(snapshot, quadrants) {
  const before = BigInt(snapshot.beforeWei), after = BigInt(snapshot.afterWei);
  const count = new Set([...quadrants].filter(q => Number.isInteger(q) && q >= 0 && q < 4)).size;
  // The draw pays one rolled budget, not four equal quarter-budgets. Start one
  // continuous drain with its first result; later reveals cannot restart it.
  return count > 0 ? after : before;
}

export function createJackpotPoolReplay({ load, changed, schedule = setTimeout, cancel = clearTimeout,
  afterPaint = fn => fn(), waitForDrain = null }) {
  const cache = new Map();
  const resolved = new Map();
  let active = null, advanceTimer = null, fillTimer = null;
  const clearAdvance = () => {
    if (advanceTimer != null) cancel(advanceTimer);
    if (fillTimer != null) cancel(fillTimer);
    advanceTimer = fillTimer = null;
  };
  const advanceAfterDrain = run => {
    if (!run.snapshot || !run.drained || run.quadrants.size < 4 || run.nextDay || run.finished) return;
    const count = Number(run.snapshot.jackpotDays) === 1 ? 1 : 3;
    const final = Number(run.snapshot.counter) + 1 >= count;
    if (final) {
      run.finished = true;
      run.holdFill = true;
      // Change the labels while the tube is empty, then animate the new fill.
      fillTimer = schedule(() => {
        fillTimer = null;
        if (active !== run) return;
        run.holdFill = false;
        changed();
      }, 220);
    } else run.nextDay = true;
    changed();
  };
  const drain = run => {
    if (!run.snapshot || !run.quadrants.size || run.drainQueued) return;
    run.drainQueued = true;
    // Late snapshots must paint their starting amount before any debit. This
    // also prevents a skipped spin from combining start and end in one frame.
    afterPaint(() => {
      if (active !== run) return;
      run.drainStarted = true;
      changed();
      const settled = () => {
        if (active !== run) return;
        run.drained = true;
        advanceAfterDrain(run);
      };
      if (waitForDrain) Promise.resolve().then(waitForDrain).then(settled, settled);
      else advanceTimer = schedule(() => { advanceTimer = null; settled(); }, 1200);
    });
  };
  const warm = day => {
    if (!Number.isInteger(day) || day < 1) return Promise.resolve(null);
    if (!cache.has(day)) {
      const pending = Promise.resolve().then(() => load(day)).then(value => {
        if (value?.status !== 'resolved' || !value.jackpot) { cache.delete(day); return null; }
        const before = BigInt(value.beforeWei), after = BigInt(value.afterWei);
        if (before <= 0n || after < 0n || after > before) throw Error('Invalid pool snapshot');
        resolved.set(day, value);
        return value;
      }).catch(() => { cache.delete(day); return null; });
      cache.set(day, pending);
    }
    return cache.get(day);
  };
  return {
    warm,
    select(day, { preview = false, player = null } = {}) {
      if (active && active.day !== day) { clearAdvance(); active = null; changed(); }
      if (!preview || active) { void warm(day); return; }
      const snapshot = resolved.get(day) ?? null;
      const run = active = { day, player, quadrants: new Set(), snapshot, loading: !snapshot };
      changed();
      void warm(day).then(snapshot => {
        if (active !== run) return;
        run.snapshot = snapshot;
        run.loading = false;
        changed();
      });
    },
    begin(detail) {
      if (detail.bonusPhase) return;
      clearAdvance();
      active = null;
      if (detail.phase !== 'J') { changed(); return; }
      const snapshot = resolved.get(detail.day) ?? null;
      const run = active = { ...detail, quadrants: new Set(), snapshot, loading: !snapshot };
      changed();
      void warm(detail.day).then(snapshot => {
        if (active !== run) return;
        run.snapshot = snapshot;
        run.loading = false;
        changed();
        drain(run);
      });
    },
    reveal(detail) {
      if (!active || detail.bonusPhase || detail.runId !== active.runId || detail.day !== active.day
        || detail.player !== active.player || !Number.isInteger(detail.quadrant)
        || detail.quadrant < 0 || detail.quadrant > 3 || active.quadrants.has(detail.quadrant)) return;
      active.quadrants.add(detail.quadrant);
      changed();
      drain(active);
      advanceAfterDrain(active);
    },
    progress(detail) {
      if (!active || detail.bonusPhase || Number(detail.day) !== active.day || detail.player !== active.player
        || (detail.runId != null && detail.runId !== active.runId)) return;
      let added = false;
      for (let q = 0; q < 4; q++) {
        if (!Number.isInteger(detail.traits?.[q]) || active.quadrants.has(q)) continue;
        active.quadrants.add(q); added = true;
      }
      if (added) { changed(); drain(active); advanceAfterDrain(active); }
    },
    complete(detail) {
      if (!active || detail.bonusPhase || Number(detail.day) !== active.day || detail.player !== active.player
        || (detail.runId != null && detail.runId !== active.runId)) return;
      active.quadrants = new Set([0, 1, 2, 3]);
      changed();
      drain(active);
      advanceAfterDrain(active);
    },
    reset() { clearAdvance(); active = null; changed(); },
    get pending() { return active?.loading === true; },
    get settling() { return Boolean(active?.snapshot && active.quadrants.size > 0
      && ((!active.nextDay && !active.finished) || active.holdFill)); },
    get value() {
      if (!active?.snapshot) return null;
      if (active.finished) return { ...active.snapshot, currentWei: BigInt(active.snapshot.afterWei), revealed: 4,
        finished: true, holdFill: active.holdFill };
      if (active.nextDay) return { ...active.snapshot, beforeWei: active.snapshot.afterWei,
        counter: Number(active.snapshot.counter) + 1, currentWei: BigInt(active.snapshot.afterWei), revealed: 0, nextDay: true };
      return { ...active.snapshot, currentWei: active.drainStarted
        ? revealedPoolWei(active.snapshot, active.quadrants) : BigInt(active.snapshot.beforeWei),
        revealed: active.quadrants.size, draining: active.drainStarted === true };
    },
  };
}
